pnpm -s exec tsx -e 'import fs from "node:fs"; import { parseBytecodeModule } from "./src/bytecodeReader";
const tsMod=parseBytecodeModule(fs.readFileSync("artifacts_tmp_test_closure3_repro/test_closure3.ts.qbc")) as any;
const wasmMod=parseBytecodeModule(fs.readFileSync("artifacts_tmp_test_closure3_repro/test_closure3.wasm.qbc")) as any;

function getVarDefs(f:any): any[] { return (f?.varDefs ?? f?.vardefs ?? f?.vars ?? f?.var_defs ?? []) as any[]; }
function dumpFunc(label:string, f:any, prefix:string){
  if(!f||typeof f!=="object") return;
  const tag=f.tag;
  if(tag!==12) return;
  const vds=getVarDefs(f);
  console.log(prefix+label, {funcName:f.funcName, argCount:f.argCount, varCount:f.varCount, vdsLen:vds.length});
  for(let i=0;i<vds.length;i++){
    const vd=vds[i];
    console.log(prefix+"  vd["+i+"]", {name: vd?.name ?? vd?.varName, scopeLevel: vd?.scopeLevel, scopeNextPlus1: vd?.scopeNextPlus1, flags: vd?.flags});
  }
}

function walk(label:string, mod:any){
  const root=mod.func;
  const cp=root.cpool||[];
  for(let i=0;i<cp.length;i++){
    const f=cp[i];
    if(f && typeof f==="object" && f.tag===12){
      dumpFunc(label, f, `root.cpool[${i}] `);
      const sub=f.cpool||[];
      for(let j=0;j<sub.length;j++){
        const sf=sub[j];
        if(sf && typeof sf==="object" && sf.tag===12){
          dumpFunc(label, sf, `  root.cpool[${i}].cpool[${j}] `);
        }
      }
    }
  }
}

console.log("\n--- TS ---");
walk("TS", tsMod);
console.log("\n--- WASM ---");
walk("WASM", wasmMod);
'

